shader:
// Impact Flash v3 - a punch on the cut, timed in SECONDS around the cut (frame-rate safe at 30 fps).
//  A  : crisp until ~45 ms before the cut, then a t^3 push-in 1.0 -> 1.035 and an eased exposure ramp
//       (pure exposure + filmic shoulder: highlights blow out first, blacks stay black - never milky).
//  CUT: a 38 ms full-white plateau (> one 33 ms frame, so every 30 fps phase gets a white peak frame), reached
//       by +8 stops of exposure (colours brighten, bleed to white, never a grey veil); only at the very top a
//       mix finishes true blacks to a slightly warm white. The hard cut sits inside the plateau.
//  B  : lands with a zoom kick 1.06 -> 1.0 and a coherent 7.5 Hz decaying shake (hits ~ -11 / +3.5 / -1 px
//       at 960, each spanning 2 frames at 30 fps), exposure tail tau 40 ms, pixel-exact from +240 ms.
// Motion blur: 180-degree shutter (half a 30 fps frame), the whole camera re-evaluated per tap. Three paths
// picked by uniform-only conditions (<= 42 texture reads per pixel):
//   flash/split : 14 taps x 3 channel fetches (RGB split <= 2 px outside the white; defocus/streak only in it)
//   sharp       : 1-8 time taps x 5-fetch Catmull-Rom (pixel-faithful, no bilinear softening, no jitter)
//   long blur   : 40 bilinear taps, per-pixel jitter only when the steps would show
const float IF_DUR = 0.45;     // preset duration, s   (must match impact-flash.json "duration")
const float IF_CUT = 0.30;     // preset anchor        (must match impact-flash.json "anchor")
const float IF_SHUT = 0.0167;  // shutter, s: half a frame at 30 fps
const int IF_N3 = 14;          // split path: 14 x 3 = 42 reads
const int IF_NS = 8;           // sharp path: up to 8 x 5 = 40 reads
const int IF_N1 = 40;          // long-blur path: 40 x 1 = 40 reads

struct IFCam { float zoom; vec2 off; float roll; float fl; float w; };

float if_hash(vec2 px) {                       // Hoskins hash12 (no sin)
  vec3 p3 = fract(vec3(px.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// camera + light state at dt seconds from the cut
IFCam if_cam(float dt) {
  IFCam c;
  float tail = 1.0 - smoothstep(0.88, 1.0, IF_CUT + dt / IF_DUR);   // everything lands exactly on clean B
  if (dt < 0.0) {
    float t = clamp(1.0 + dt / 0.045, 0.0, 1.0);   // the push-in rushes into the flash (last 45 ms): A stays crisp before
    float e = smoothstep(-0.075, -0.012, dt);
    c.zoom = 1.0 + 0.035 * kick * t * t * t;
    c.off = vec2(0.0);
    c.roll = 0.0;
    c.fl = e * e;                                  // strong ease-in of the exposure into the cut
    c.w = smoothstep(-0.020, -0.008, dt);
  } else {
    float settle = tail * (1.0 - smoothstep(0.16, 0.24, dt));        // B is pixel-exact from +240 ms
    float env = exp(-dt / 0.06) * settle;
    float ph = 6.2831853 * 7.5 * dt;
    float amp = 0.034 * shake * env;
    c.off = amp * vec2(0.45 * cos(ph - 0.15), cos(ph));   // one coherent jolt: the hit frames hold still
    c.roll = 0.0139626 * shake * env * cos(ph);
    // zoom kick, plus a small cover zoom on the shake envelope so no mirrored edge shows
    c.zoom = (1.0 + 0.06 * kick * exp(-dt / 0.06) * settle) * (1.0 + 0.6 * amp);
    c.fl = (dt < 0.030 ? 1.0 : exp(-(dt - 0.030) / 0.040)) * tail;
    c.w = 1.0 - smoothstep(0.030, 0.042, dt);
  }
  return c;
}

// output position (centred, aspect-corrected) -> source uv for a camera state
vec2 if_src(IFCam c, vec2 q0, vec2 disc, float spread, float k, vec2 asp) {
  float cr = cos(c.roll);
  float sr = sin(c.roll);
  vec2 q = mat2(cr, sr, -sr, cr) * q0;
  q = q / (c.zoom * (1.0 + spread)) + c.off + disc;
  return q * (1.0 + k) / asp + 0.5;
}

vec3 if_get(bool onA, vec2 u) {
  vec3 s;
  if (onA) { s = getA(u).rgb; } else { s = getB(u).rgb; }
  return s;
}

// Catmull-Rom in 5 bilinear fetches (corner taps dropped, weights renormalised)
vec3 if_getCR(bool onA, vec2 u, vec2 ts) {
  vec2 sp = u * ts;
  vec2 t1 = floor(sp - 0.5) + 0.5;
  vec2 f = sp - t1;
  vec2 w0 = f * (-0.5 + f * (1.0 - 0.5 * f));
  vec2 w1 = 1.0 + f * f * (-2.5 + 1.5 * f);
  vec2 w2 = f * (0.5 + f * (2.0 - 1.5 * f));
  vec2 w3 = f * f * (-0.5 + 0.5 * f);
  vec2 w12 = w1 + w2;
  vec2 p0 = (t1 - 1.0) / ts;
  vec2 p3 = (t1 + 2.0) / ts;
  vec2 p12 = (t1 + w2 / w12) / ts;
  float a = w12.x * w0.y;
  float b = w0.x * w12.y;
  float c = w12.x * w12.y;
  float d = w3.x * w12.y;
  float e = w12.x * w3.y;
  vec3 s = if_get(onA, vec2(p12.x, p0.y)) * a + if_get(onA, vec2(p0.x, p12.y)) * b + if_get(onA, p12) * c
         + if_get(onA, vec2(p3.x, p12.y)) * d + if_get(onA, vec2(p12.x, p3.y)) * e;
  return s / (a + b + c + d + e);
}

// sample -> linear light. The flash is pure EXPOSURE (per-channel filmic shoulder keeps hue: colours brighten,
// then clip to white - never a grey veil); the whiteout adds up to +8 stops so even deep shadows clip, and only
// at the very top (W ~ 1) does a mix finish true blacks to the warm white.
vec3 if_light(vec3 s, float fl, float wv, float r2) {
  vec3 x = pow(max(s, vec3(0.0)), vec3(2.2));
  float ev = flash * 4.0 * fl + 8.0 * wv;
  x *= exp2(ev);
  float ye = luma(x);                                          // exposed luminance (can exceed 1)
  float ym = max(x.r, max(x.g, x.b));                          // exposed peak channel
  vec3 sh = 0.7 + 0.3 * (1.0 - exp(-(x - 0.7) / 0.3));      // C1 shoulder above 0.7
  x = mix(x, sh, step(0.7, x) * clamp(ev * 2.0, 0.0, 1.0));   // identity while unexposed
  // an over-exposed colour bleeds to white (film-like), so saturated darks never float as coloured blobs
  float bl = max(smoothstep(0.5, 1.6, ye), smoothstep(1.0, 3.0, ym));
  x = mix(x, vec3(1.0), bl * clamp(ev * 2.0, 0.0, 1.0));
  vec3 white = vec3(1.0, 0.955, 0.875) * (1.0 - 0.05 * r2);  // slightly warm, a touch of lens falloff
  float wv2 = wv * wv;
  return mix(x, white, 0.97 * wv2 * wv2 * smoothstep(0.6, 1.0, flash));   // a soft flash stays pure exposure
}

vec4 transition(vec2 uv) {
  float dt0 = (progress - IF_CUT) * IF_DUR;
  float taper = clamp(progress * 12.0, 0.0, 1.0) * clamp((1.0 - progress) * 12.0, 0.0, 1.0);
  float win = IF_SHUT * taper;
  // the shutter never straddles the cut: a hard cut hidden in the white, never a double exposure
  bool onA = dt0 < 0.0;
  float lo = onA ? -IF_CUT * IF_DUR : 0.0;
  float hi = onA ? -0.0001 : (1.0 - IF_CUT) * IF_DUR;
  float t0 = clamp(dt0 - 0.5 * win, lo, hi);
  float t1 = clamp(dt0 + 0.5 * win, lo, hi);
  vec2 asp = vec2(ratio, 1.0);
  vec2 q0 = (uv - 0.5) * asp;
  float r2 = dot(q0, q0) * 2.0;

  // uniform-only: the frame's flash level, blur length at the corners, worst R-B separation
  IFCam cc = if_cam(dt0);
  IFCam ca = if_cam(t0);
  IFCam cb = if_cam(t1);
  float wv = cc.w * clamp(flash, 0.0, 1.0);       // the whiteout is a per-frame event (no shutter veil)
  vec2 k1 = vec2(0.5 * ratio, 0.5);
  vec2 k2 = vec2(-0.5 * ratio, 0.5);
  float blurPx = max(length((if_src(cb, k1, vec2(0.0), 0.0, 0.0, asp) - if_src(ca, k1, vec2(0.0), 0.0, 0.0, asp)) * resolution),
                     length((if_src(cb, k2, vec2(0.0), 0.0, 0.0, asp) - if_src(ca, k2, vec2(0.0), 0.0, 0.0, asp)) * resolution));
  float kMax = chroma * 0.0020 * max(ca.fl, cb.fl);
  bool split = cc.w > 0.0 || kMax * resolution.y > 0.8;

  vec2 px = floor(uv * resolution);
  float jit = if_hash(px) - 0.5;
  vec3 acc = vec3(0.0);
  if (split) {
    float rot = if_hash(px + vec2(37.0, 113.0)) * 6.2831853;
    float w4 = cc.w * cc.w * cc.w * cc.w * smoothstep(0.6, 1.0, flash);   // lens effects only in a real whiteout
    float ja = clamp(blurPx / float(IF_N3) - 0.5, 0.0, 1.0);
    for (int i = 0; i < IF_N3; i++) {
      float f = (float(i) + 0.5 + ja * jit) / float(IF_N3);
      float tq = mix(t0, t1, f);
      IFCam cg = if_cam(tq);
      float dtc = 0.004 * chroma * w4;                         // temporal split only inside the white
      IFCam cr = if_cam(clamp(tq + dtc, lo, hi));
      IFCam cl = if_cam(clamp(tq - dtc, lo, hi));
      float k = chroma * (0.0020 * cg.fl + 0.004 * w4);         // radial split: <= 2 px R-B outside the white
      float spread = 0.02 * flash * w4 * (f - 0.5);             // radial streak, only inside the white
      float j = mod(float(i) * 5.0, float(IF_N3));               // defocus disc, only inside the white
      float ang = j * 2.3999632 + rot;
      vec2 disc = (0.012 * flash * w4 * sqrt((j + 0.5) / float(IF_N3))) * vec2(cos(ang), sin(ang));
      vec2 uvR = if_src(cr, q0, disc, spread, k, asp);
      vec2 uvG = if_src(cg, q0, disc, spread, 0.0, asp);
      vec2 uvB = if_src(cl, q0, disc, spread, -k, asp);
      vec3 s;
      if (onA) {
        s = vec3(getA(uvR).r, getA(uvG).g, getA(uvB).b);
      } else {
        s = vec3(getB(uvR).r, getB(uvG).g, getB(uvB).b);
      }
      acc += if_light(s, cg.fl, wv, r2);
    }
    acc /= float(IF_N3);
  } else if (blurPx < 7.0) {
    vec2 ts = onA ? vec2(textureSize(uA, 0)) : vec2(textureSize(uB, 0));
    int nt = int(clamp(ceil(blurPx) + 1.0, 1.0, float(IF_NS)));
    for (int i = 0; i < IF_NS; i++) {
      if (i >= nt) { break; }
      float f = (float(i) + 0.5) / float(nt);
      IFCam cg = if_cam(mix(t0, t1, f));
      acc += if_light(if_getCR(onA, if_src(cg, q0, vec2(0.0), 0.0, 0.0, asp), ts), cg.fl, wv, r2);
    }
    acc /= float(nt);
  } else {
    float ja = clamp(blurPx / float(IF_N1) - 0.5, 0.0, 1.0);
    for (int i = 0; i < IF_N1; i++) {
      float f = (float(i) + 0.5 + ja * jit) / float(IF_N1);
      IFCam cg = if_cam(mix(t0, t1, f));
      acc += if_light(if_get(onA, if_src(cg, q0, vec2(0.0), 0.0, 0.0, asp)), cg.fl, wv, r2);
    }
    acc /= float(IF_N1);
  }
  // triangular +-1 LSB dither while the flash is on: the near-flat cream field never bands (exact A / B at the ends)
  float dith = (if_hash(px + vec2(71.0, 19.0)) + if_hash(px + vec2(5.0, 233.0)) - 1.0) / 255.0 * clamp(max(cc.fl, cc.w) * 4.0, 0.0, 1.0);
  return vec4(pow(max(acc, vec3(0.0)), vec3(1.0 / 2.2)) + dith, 1.0);
}
